import { BoundingBox } from "#core/scripts/external/TypeScript-Voronoi-master/src/bounding_box.js";
import { Diagram } from "#core/scripts/external/TypeScript-Voronoi-master/src/diagram.js";
import { Site } from "#core/scripts/external/TypeScript-Voronoi-master/src/site.js";

import { profileFunction } from "#base/scripts/profiling.js";
import { VoronoiUtils, WrapType } from "#base/scripts/voronoi-utils.js";

export class VoronoiBuilder {
	private m_diagram: Diagram = new Diagram();
	private m_diagramDims: float2 = { x: 0, y: 0 };
	private m_wrap: WrapType = WrapType.None;

	constructor() {}

	public init(hexDims: float2, cellCountMultiple: number, relaxationSteps: number, wrap: WrapType = WrapType.None) {
		this.m_diagramDims = { x: hexDims.x * Math.sqrt(3) * 0.5, y: hexDims.y * 0.75 };
		this.m_wrap = wrap;
		const totalCells = hexDims.x * hexDims.y * cellCountMultiple;

		console.log("Initializing voronoi-builder");
		console.log("  Diagram dims: {x:" + this.m_diagramDims.x + ", y:" + this.m_diagramDims.y + "}");
		console.log("  Total cells: " + totalCells + ", relaxed " + relaxationSteps + " times.");
		this.buildVoronoi(this.m_diagramDims.x, this.m_diagramDims.y, totalCells, relaxationSteps, wrap);
		console.log("  voronoi built...");
	}

	public getDiagram(): Diagram {
		return this.m_diagram;
	}

	public getDiagramDims(): float2 {
		return this.m_diagramDims;
	}

	private buildVoronoi(
		width: number,
		height: number,
		cellCount: number,
		relaxationSteps: number,
		wrap: WrapType = WrapType.None,
	) {
		const bbox: BoundingBox = { xl: 0, xr: width, yt: 0, yb: height }; // xl is x-left, xr is x-right, yt is y-top, and yb is y-bottom
		const sites: Site[] = VoronoiUtils.createRandomSites(cellCount, width, height);
		this.m_diagram = profileFunction("Compute Voronoi", () =>
			VoronoiUtils.computeVoronoi(sites, bbox, relaxationSteps, wrap),
		);
	}
}
